# Print more of the results
if not claim_raw.startswith("[read_file error]") and len(claim_raw) > 3000:
    print(claim_raw[3000:7000])

import json

# Parse the claim results
if not claim_raw.startswith("[read_file error]"):
    cr = json.loads(claim_raw)

    def get_result(step_key):
        stdout = cr.get(step_key, {}).get('stdout', '')
        if stdout:
            try:
                return json.loads(stdout).get('result', {})
            except:
                return {"raw": stdout[:500]}
        return {"error": "no output", "stderr": cr.get(step_key, {}).get('stderr', '')[:300]}

    order_r = get_result('step1')
    warranty_r = get_result('step2')
    confirm_r = get_result('step5')
    verify_r = get_result('step6')

    print("Order:", json.dumps(order_r, indent=2)[:500])
    print("\nWarranty:", json.dumps(warranty_r, indent=2)[:500])
    print("\nConfirm:", json.dumps(confirm_r, indent=2)[:500])
    print("\nVerify:", json.dumps(verify_r, indent=2)[:500])
else:
    print("No results file available")
